import * as THREE from 'three/webgpu';
import { texture, attribute, mul, add } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();
  container.position.set(-1.25, 0.7, 0);

  // Load textures via context loader (cached)
  const colorTexture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthTexture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');

  // Create tessellated plane for displacement mapping
  const geometry = new THREE.PlaneGeometry(2.0, 1.25, 64, 64);

  // TSL nodes for vertex displacement
  const positionAttribute = attribute('position');
  const normalAttribute = attribute('normal');
  const depthMapNode = texture(depthTexture);

  // Displace vertices along normals based on depth map intensity
  const displacementIntensity = 0.15;
  const displacedPosition = add(
    positionAttribute,
    mul(normalAttribute, mul(depthMapNode.r, displacementIntensity))
  );

  // Color texture node
  const colorNode = texture(colorTexture);

  // Create machined-metal material with physical parameters
  const material = new THREE.MeshPhysicalMaterial({
    map: colorTexture,
    metalness: 0.45,
    roughness: 0.65,
    clearcoat: 0.15,
    clearcoatRoughness: 0.8,
    emissive: new THREE.Color(0x000000),
    toneMapped: false,
  });

  // Apply TSL node graph (WebGPU automatic node material)
  material.colorNode = colorNode;
  material.positionNode = displacedPosition;

  const mesh = new THREE.Mesh(geometry, material);
  container.add(mesh);

  // Apply cinematic primitive: parallax-scroll
  if (ctx.primitives?.['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](container, { intensity: 0.25 });
  }

  // Interaction handlers
  container.userData.handlers = {
    onHover: () => {
      gsap.killTweensOf(mesh.position);
      gsap.to(mesh.position, {
        y: 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
    },

    onHoverOut: () => {
      gsap.killTweensOf(mesh.position);
      gsap.to(mesh.position, {
        y: 0,
        duration: 0.7,
        ease: 'power3.out'
      });
    },

    onClick: () => {
      gsap.killTweensOf(mesh.scale);
      gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(mesh.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.3,
            ease: 'power2.out'
          });
        }
      });

      if (config.handlers?.onClick) {
        config.handlers.onClick({ event: 'hub-features.select' });
      }
    },

    onFocus: () => {
      gsap.to(material.emissive, {
        r: 1.0,
        g: 0.16,
        b: 0.22,
        duration: 0.3,
        ease: 'power2.out'
      });
    },

    onBlur: () => {
      gsap.to(material.emissive, {
        r: 0,
        g: 0,
        b: 0,
        duration: 0.3,
        ease: 'power2.out'
      });
    }
  };

  container.userData.cleanup = () => {
    gsap.killTweensOf([mesh.position, mesh.scale, material.emissive]);
    geometry.dispose();
    material.dispose();
    colorTexture.dispose();
    depthTexture.dispose();
  };

  return container;
}
